def division(lst):
    even = odd = 0
    for num in lst:
        if num % 2 == 0:
            even += 1
        else:
            odd += 1
    if even > 1:
        return "Even numbers: 1"
    elif odd > 1:
        return "Odd numbers: 1"
    else:
        return "All numbers are even or odd"

# Example usage:
